D[2647]={"^|cFF66DDFFLevel 10 Passive|r\nYour |cffffffffGaze of C'Thun|r now gains an additional (.-) base damage and healing%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nSeu |cffffffffOlhar de C'Thun|r agora ganha {{1}} de dano e cura base adicional."}
D[3395]={"^While |cffffffffBlack Blood|r is active on an ally, healing done to them by your |cffffffffGaze of C'Thun|r has a (.-)%% increased chance to critically strike%.%s*$","Enquanto que o |cffffffffSangue Negro|r estiver ativo em um aliado, a cura que recebida do seu |cffffffffOlhar de C'Thun|r tem uma maior chance de {{1}}% de ser crítica."}
D[3404]={"^|cFF66DDFFLevel 15 Passive|r\nWhile above 40 |cffcfa6ffInsanity|r, your melee attacks now reduce the cooldown of your |cFFFFFFFFGaze of C'thun|r by (.-) sec%.%s*$","|cFF66DDFFPassivo de Nível 15|r\nEnquanto estiver acima de 40 |cffcfa6ffDemência|r, seus ataques corpo a corpo agora reduzem a recarga de sua |cFFFFFFFFOlhar de C'Thun|r em {{1}} s."}
D[3407]={"^Increases the healing and bonus healing of |cFFFFFFFFGaze of C'Thun|r and |cffffffffEldritch Mending|r by (.-)%%%.%s*$","Aumenta a cura e o poder adicional de cura de |cFFFFFFFFOlhar de C'Thun|r e |cffffffffRecomposição Sobrenatural|r em {{1}}%."}
D[3413]={"^Casting |cffffffffHerald of the Depths|r now increases the absorption of your next |cffffffffVoid Shield|r within (.-) by (.-)%%%.%s*$","Lançar |cffffffffArauto do abismo|r agora aumenta a absorção de seu próximo |cffffffffEscudo de vazio|r em {{1}} {{2}}%."}
D[3417]={"^Casting |cffffffffGaze of C'thun|r now always triggers your |cffffffffPresence of C'Thun|r while it is active%.%s*$","Lançar |cffffffffOlhar de C'Thun|r agora sempre ativa |cffffffffPresença de C'thun|r enquanto o efeito estiver ativo."}
D[3418]={"^Casting |cFFFFFFFFGaze of C'Thun|r now reduces the cooldown of |cffffffffPsychic Suppression|r and |cffffffffGrasp of Zek'voz|r by (.-) sec%.%s*$","O lançamento de |cFFFFFFFFOlhar de C'Thun|r agora reduz a recarga de |cffffffffSupressão psíquica|r e |cffffffffAgarrão de Zek'voz|r em {{1}} s."}
D[3423]={"^Increases the spell damage bonus of |cFFFFFFFFHorrorbolt|r by (.-)%% and |cFFFFFFFFWrath of the Empire|r by (.-)%%%.%s*$","Aumenta o bônus de dano com feitiços de |cFFFFFFFFSeta de Horror|r em {{1}}% e de |cFFFFFFFFIra do Império|r em {{2}}%."}
D[3424]={"^Increases the critical strike chance of |cffffffffWrath of the Black Empire|r by (.-)%%%.%s*$","Aumenta a chance de acerto crítico de |cffffffffIra do Império Negro|r em {{1}}%."}
D[3428]={"^Reduces the cast time of |cffffffffHorrorbolt|r and |cffffffffWrath of the Black Empire|r by 0%.3 sec%.%s*$","Reduz o tempo de lançamento de |cffffffffSeta de Horror|r e |cffffffffIra do Império Negro|r em 0.3 s."}
D[3430]={"^Reduces the cooldown of |cffffffffPsychic Suppression|r by (.-) sec%.%s*$","Reduz a recarga de |cffffffffSupressão psíquica|r em {{1}} s."}
D[3432]={"^|cFF66DDFFLevel 40 Passive|r\nGrants all periodic damage and damage dealt a (.-)%% chance to reset the cooldown of |cffffffffGaze of C'Thun|r and generate 5 |cffcfa6ffInsanity|r%.%s*$","|cFF66DDFFPassivo de Nível 40|r\nConcede a todo o dano e cura periódicos {{1}}% de chance de reiniciar a recarga de |cffffffffOlhar de C'Thun|r e gerar 5 |cffcfa6ffDemência|r."}
D[3739]={"^Increases the duration of |cffffffffVoid Embrace|r by (.-) sec%.%s*$","Aumenta a duração de |cffffffffAbraço do Vazio|r em {{1}} s."}
D[3741]={"^Dealing damage with |cffffffffGaze of C'Thun|r now reduces the cooldown of |cffffffffTentacle of C'Thun|r by (.-) sec%.%s*$","Causar dano com |cffffffffOlhar de C'Thun|r agora reduz a recarga de |cffffffffTentáculo de C'thun|r em {{1}} s."}
D[3789]={"^Shields an ally, absorbing (.-) damage for (.-) and applying |cffffffffWracked Mind|r%.%s*$","Protege um aliado, absorvendo {{1}} de dano durante {{2}} e aplicando |cffffffffMente desgarrada|r."}
D[3896]={"^Set C’thun’s Gaze upon an enemy or ally, jumping to 1 additional nearby target, dealing (.-) Shadow damage to enemies or healing allies for (.-) and revealing stealthed enemies within (.-)%.%s*$","Estabelece a olhar de C’thun sobre um inimigo ou aliado, saltando a 1 alvo próximo adicional, causando {{1}} de dano de Sombra aos inimigos ou curando os aliados em {{2}} e revelando os inimigos escondidos dentro de {{3}}."}
