D[76515]={"^Reaching 100 |cffcfa6ffInsanity|r no longer causes |cFFFFFFFFTotal Madness|r%.\n\nTeaches you |cffffffffDreadnought|r%.%s*$","Ao alcançar 100 |cffcfa6ffDemência|r não causa |cFFFFFFFFLoucura Total|r.\n\nEnsina |cffffffffCouraçado|r."}
D[76650]={"^|cFFFFFFFFVoid Shield|r now reduces the cooldown of |cFFFFFFFFHallucination|r by 10 sec%.%s*$","|cFFFFFFFFEscudo de vazio|r agora reduz a recarga de |cFFFFFFFFAlucinação|r em 10 s."}
D[76664]={"^While above 60 |cffcfa6ffInsanity|r, your |cFFFFFFFFNetherstrike|r and |cffffffffGaze of C'Thun|r now gain (.-)%% increased critical strike chance%.%s*$","Enquanto estiver acima de 60 de |cffcfa6ffDemência|r, |cFFFFFFFFGolpe Etéreo|r e |cffffffffOlhar de C'Thun|r recebem {{1}}% a mais de chance de acerto crítico."}
D[76766]={"^While above 60 |cffcfa6ffInsanity|r, the cooldown of your |cFFFFFFFFTwilight Shieldtoss|r and |cFFFFFFFFGaze of C'thun|r is reduced by (.-)%%%.%s*$","Enquanto estiver acima de 60 |cffcfa6ffDemência|r, a recarga de sua |cFFFFFFFFTiro de Escudo Crepúsculo|r e |cFFFFFFFFOlhar de C'Thun|r é reduzido em {{1}}%."}
D[76837]={"^Casting |cFFFFFFFFHorrorbolt|r now grants |cFFFFFFFFInspired Malice|r for (.-)%.%s*$","Lançar |cFFFFFFFFSeta de Horror|r agora concede a você |cFFFFFFFFMalícia inspirada|r durante {{1}}."}
D[76920]={"^Absorbs (.-) damage, scaling with Intellect and Stamina%. Protects movement speed from going below (.-)%% of normal speed%. Lasts (.-)%.\n\nDepletes all |cffcfa6ffInsanity|r upon expiration%.%s*$","Absorve {{1}} de dano, escalando com Intelecto e Vigor. Protege a velocidade de movimento para que não bagem de {{2}}% da velocidade normal. Dura {{3}}.\n\nEsgota toda |cffcfa6ffDemência|r ao expirar."}
D[76977]={"^While above 80 Insanity, the cooldown of |cFFFFFFFFVoid Shield|r is reduced by (.-) sec%.%s*$","Enquanto estiver acima de 80 Loucura, a recarga de |cFFFFFFFFEscudo de vazio|r é reduzido em {{1}} s."}
D[77222]={"^Empower party and raid members with a |cffffffffVoid Blessing|r, restoring (.-) mana every 5 seconds for (.-)%.%s*$","Fortalece os membros do grupo e da raide com uma |cffffffffBênção do Vazio|r, restaurando {{1}} de mana a cada 5 s durante {{2}}."}
D[77302]={"^|cFF66DDFFLevel 10 Passive|r\nReaching 100 |cffcfa6ffInsanity|r no longer causes |cFFFFFFFFTotal Madness|r%.\n\nTeaches you |cffffffffDreadnought|r%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nAo alcançar 100 |cffcfa6ffDemência|r não causa |cFFFFFFFFLoucura Total|r.\n\nEnsina |cffffffffCouraçado|r."}
D[77349]={"^Damage dealt by |cffffffffGaze of C'thun|r has a (.-)%% chance to coalesce a |cFFFFFFFFManifestation of Y'Shaarj|r for %$680573, which will attack the target and heal you for 1%% of your base health%.%s*$","O dano causado por |cffffffffOlhar de C'Thun|r tem {{1}}% de chance de formar uma |cFFFFFFFFManifestação de E'shaarj|r durante $680573, que atacará o alvo e curará você em 1% da vida base."}
D[77393]={"^Every 5th critical strike with abilities now transforms your next |cFFFFFFFFGaze of C'Thun|r into |cFFFFFFFFEldritch Force|r%.%s*$","Cada 5a acerto crítico com habilidades transforma seu próximo |cFFFFFFFFOlhar de C'Thun|r em |cFFFFFFFFForça Sobrenatural|r."}
D[77405]={"^Every 5 ability critical strikes transforms your next |cFFFFFFFFGaze of C'Thun|r into |cFFFFFFFFEldritch Force|r%.%s*$","Cada 5 acerto crítico transforma seu próximo |cFFFFFFFFOlhar de C'Thun|r em |cFFFFFFFFForça Sobrenatural|r."}
D[77548]={"^Every 3rd |cffffffffHorrorbolt|r cast causes your next successful |cffffffffHorrorbolt|r to deal an additional 50%% of the initial damage to the target over (.-)%.%s*$","A cada terceiro lançamento de |cffffffffSeta de Horror|r, a próxima |cffffffffSeta de Horror|r bem-sucedida causa ao alvo, durante {{1}}, dano adicional equivalente a 50% do dano inicial."}
D[77549]={"^Damage dealt by |cffffffffGaze of C'Thun|r now has a (.-)%% to chance to spawn a void portal that casts either |cFFFFFFFFGaze of C'thun|r, |cFFFFFFFFHorrorbolt|r, or |cFFFFFFFFObliteration Beam|r before disappearing%.%s*$","O dano causado por |cffffffffOlhar de C'Thun|r agora tem {{1}}% de chance de criar um portal do Vazio que lança |cFFFFFFFFOlhar de C'Thun|r, |cFFFFFFFFSeta de Horror|r ou |cFFFFFFFFRaio de aniquilação|r antes de desaparecer."}
D[77550]={"^|cFFFFFFFFHorrorbolt|r now applies |cFFFFFFFFDarkness Abounds|r, increasing the damage of your next Wrath of the Black Empire by 10%% for 12 sec%.\n\nStacks 6 times%.%s*$","|cFFFFFFFFSeta de Horror|r agora aplica |cFFFFFFFFEscuridão Abundante|r, aumentando em 10% o dano do seu próximo |cFFFFFFFFIra do Império Negro|r durante 12 s.\n\nAcumula até 6 vezes."}
D[77551]={"^Increases the damage of your |cffffffffGaze of C'Thun|r by (.-)%% but it now generates 10 |cffcfa6ffInsanity|r%.%s*$","Aumenta o dano de seu |cffffffffOlhar de C'Thun|r em {{1}}% mais agora gera 10 |cffcfa6ffDemência|r."}
D[77590]={"^|cFFFFFFFFHorrorbolt|r now applies |cFFFFFFFFInner Turmoil|r while above 70 |cffcfa6ffInsanity|r%.%s*$","|cFFFFFFFFSeta de Horror|r agora aplica |cFFFFFFFFTumulto Interior|r enquanto estiver acima de 70 |cffcfa6ffDemência|r."}
D[77664]={"^Your |cffffffffGaze of C'Thun|r now strikes 1 additional nearby enemy%.%s*$","Seu |cffffffffOlhar de C'Thun|r agora atinge 1 inimigo próximo adicional."}
D[78833]={"^Increases your casting speed by 20%%%. Reduces your magical damage dealt by 15%%%. Using Nether Reach on targets affected by Void Link will now provide additional Void Runes%.Shatter Void Rune will now grant you 1 stack of Rift Weaving%.%s*$","Aumenta sua velocidade de lançamento em 20% e reduz em 15% o dano Mágico causado. Usar |cffffffffAlcance do Vazio|r em alvos afetados por |cffffffffVínculo do Vazio|r agora concede Runas do Vazio adicionais. |cffffffffEstilhaçar Runa do Vazio|r agora concede 1 acúmulo de |cffffffffTecelagem da Fissura|r."}
D[79118]={"^Your |cffffffffGaze of C'thun|r or |cFFFFFFFFObliteration Beam|r causes (.-)%% increased damage, stacks up to (.-) times%.%s*$","Seu |cffffffffOlhar de C'Thun|r ou |cFFFFFFFFRaio de aniquilação|r causa um aumento de dano em {{1}}%, acumula até {{2}} vezes."}
D[79119]={"^Your |cffffffffGaze of C'thun|r causes (.-)%% increased damage, stacks up to (.-) times%.%s*$","Seu |cffffffffOlhar de C'Thun|r causa um aumento de dano em {{1}}%, acumula até {{2}} vezes."}
D[79299]={"^|cFF66DDFFLevel 30 Passive|r\nYour |cffffffffGaze of C'Thun|r now generates 10 |cffcfa6ffInsanity|r%.%s*$","|cFF66DDFFPassivo de Nível 30|r\nSeu |cffffffffOlhar de C'Thun|r agora gera 10 |cffcfa6ffDemência|r."}
D[81421]={"^Your Crusader Strike reduce the cast time of your next Immolate, and gives it 2%% attack power scaling%. Stacking 3 times%.%s*$","Seu Golpe do Cruzado reduz o tempo de lançamento do seu próximo Imolar e concede a ele escalonamento de 2% do Poder de Ataque. Acumula até 3 vezes."}
D[82967]={"^Your Incinerate and Soul Fire reduce the cooldown of Hand of Gul'dan by 1 sec%. Critical hits reduces the cooldown by 2 sec%.%s*$","Seu Incinerar e Fogo d'Alma reduzem a recarga de Mão de Gul'dan em 1 s. Os acertos críticos reduzem a recarga em 2 s."}
D[87995]={"^Bestows the wearer with the evil aura of a Twilight's Hammer cultist%.%s*$","Lhe concede ao portador o aura malvada de um cultor Impacto."}
D[87996]={"^When worn with the Twilight Trappings Set, allows access to a Wind Stone in Silithus%.%s*$","Ao lhevá-lo com o conjunto Impacto dá acesso a uma pedra de vento em Silithus."}
D[87998]={"^When worn with the Twilight Trappings Set and the Medallion of Station, allows access to a Greater Wind Stone%.%s*$","Ao lhevá-lo com o conjunto Impacto e o medalhão de status dá acesso a uma pedra de vento superior."}
D[93008]={"^A protective void bubble emanates from the caster's shield, reducing all damage taken by (.-)%% for (.-)%.%s*$","Uma bolha protetora de vazio emana do escudo conjurador, reduzindo todo o dano recebido {{1}}% durante {{2}}."}
D[93270]={"^Heals target for (.-)%.%s*$","Cura {{1}} o alvo."}
D[94706]={"^Curses all nearby enemies, inflicting (.-) Shadow damage every (.-) sec and reducing attack and casting speeds by (.-)%% for (.-)%.%s*$","Amaldiçoa todos os inimigos próximos, causa {{1}} de dano de Sombra a cada {{2}} s e reduz as velocidades de ataque de lançamento {{3}}% durante {{4}}."}
D[94798]={"^Deals (.-) shadow damage%.%s*$","Causa {{1}} de dano de Sombra."}
D[94922]={"^Pass yourself as a member of the Cult of the Damned%.  Looks out of place outside the Cathedral of Darkness%.%s*$","Passa por um membro do Culto dos Malditos. Queda ruim fora da Catedral dá Escuridão."}
D[96426]={"^Teleports the caster to a Soul Tower%.%s*$","Teletransporta ao conjurador a uma torre de alma."}
D[98245]={"^Your melee critical strikes reduce the cooldown of |cffffffffRift|r and |cffffffffGaze of C'Thun|r by (.-) sec%.%s*$","Seus acertos críticos corpo a corpo reduzem em {{1}} s a recarga de |cffffffffFissura|r e |cffffffffOlhar de C'Thun|r."}
D[98411]={"^Your next |cFFFFFFFFGaze of C'thun|r, |cFFFFFFFFDarkwither|r or |cFFFFFFFFWrath of the Black Empire|r will be empowered%.\n\n|cFFFFFFFFGaze of C'thun:|r Critical strike chance increased by (.-)%%%.\n\n|cFFFFFFFFDarkwither:|r Shadow damage dealt increased by (.-)%% and damage of |cFFFFFFFFDarkwither|r by an additional (.-)%% for (.-)%.\n\n|cFFFFFFFFWrath of the Black Empire:|r Deals (.-)%% increased damage%.%s*$","Seu próximo |cFFFFFFFFOlhar de C'Thun|r, |cFFFFFFFFDefinhamento Sombrio|r ou |cFFFFFFFFIra do Império Negro|r será fortalecido.\n\n|cFFFFFFFFOlhar de C'Thun:|r aumenta em {{1}}% a chance de acerto crítico.\n\n|cFFFFFFFFDefinhamento Sombrio:|r aumenta em {{2}}% o dano de Sombra causado e em mais {{3}}% o dano de |cFFFFFFFFDefinhamento Sombrio|r durante {{4}}.\n\n|cFFFFFFFFIra do Império Negro:|r causa {{5}}% a mais de dano."}
D[98417]={"^|cFFFFFFFFVoid Shield|r now applies to an additional nearby ally but its duration is reduced by (.-)%%%.\n\nKilling an opponent that yields experience or honor removes |cFFFFFFFFWracked Mind|r from you%.%s*$","|cFFFFFFFFEscudo de vazio|r agora também é aplicado a mais um aliado próximo, mas sua duração é reduzida em {{1}}%.\n\nMatar um oponente que conceda experiência ou honra remove |cFFFFFFFFMente desgarrada|r de você."}
D[98435]={"^At (.-) stacks, your next |cffffffffGaze of C'Thun|r will pull targets to you, and deal (.-) additional Shadow Damage if they're an enemy%.%s*$","Com {{1}} aplicações, seu próximo |cffffffffOlhar de C'Thun|r puxará os alvos até você e causará {{2}} de dano de Sombra adicional caso sejam inimigos."}

