T[11026]={"^The Cultist's Gaze of C'thun or Obliteration Beam deals (.-)%% increased damage to you%.%s*$","A olhar do Cultista de C'thun ou o faça de Obliteração te causam {{1}}% dano adicional."}
T[11210]={"^Absorbs damage%. Next |cffffffffHorrorbolt|r or |cffffffffAbyssal Reconstruction|r will consume this effect to do (.-)%% increased damage or healing%.%s*$","Absorve dano. A próxima |cffffffffSeta de Horror|r ou |cffffffffReconstrução Abissal|r consumirá este efeito para fazer {{1}}% a mais de dano ou cura."}
T[11237]={"^Cannot be affected by Void Shield%.%s*$","não pode ser afetado por Escudo do Vazio."}
T[11444]={"^Blade of the Empire now grants (.-)%% of your Intellect as Spell Critical Strike Rating for (.-), stacking 5 times%.%s*$","|cffffffffLâmina do Império|r agora concede, durante {{2}}, índice de acerto crítico com feitiços equivalente a {{1}}% do seu Intelecto, acumulando até 5 vezes."}
T[14053]={"^Reaching 3 stacks transforms your Horrorbolt into Horrorbolt Volley%.%s*$","Ao atingir 3 acúmulos, sua Seta de Horror se transforma em Salva de Setas de Horror."}
T[14058]={"^Protected by a thick layer of shadow%.\n\nAll damage taken reduced by (.-)%%%.%s*$","Protegido por uma grossa capa de sombras.\n\nTodos dano recebido é reduzido em {{1}}%."}
T[14154]={"^|cffffffffGaze of C'thun|r now reduces the casting speed of your next 2 |cffffffffHorrorbolts|r or |cffffffffEldritch Mendings|r by (.-)%% for (.-)%.%s*$","|cffffffffOlhar de C'Thun|r reduz em {{1}}% o tempo de lançamento dos seus próximos 2 |cffffffffRaios de Horror|r ou |cffffffffReparos Sobrenaturais|r por {{2}}."}
T[14168]={"^Dealing damage with |cffffffffGaze of C'Thun|r now reduces the cooldown of |cffffffffTentacle of C'Thun|r by (.-) sec%.%s*$","Causar dano com |cffffffffOlhar de C'Thun|r agora reduz a recarga de |cffffffffTentáculo de C'thun|r em {{1}} s."}
T[14330]={"^You are transformed into a Faceless Destroyer%. Gaining 1 Insanity and 1 Void Rune every (.-) sec%.%s*$","Você se transforma em um Destruidor Anônimo. Obtém 1 Insanidade e 1 Runa do Vazio a cada {{1}} s."}
T[14331]={"^You are transformed into a Faceless Destroyer%.\n\nWhile transformed, you deal (.-)%% increased damage, and take (.-)%% reduced damage%. Every (.-) sec you will generate 10 Insanity and summon a Tentacle of N'zoth nearby%. In addition, all enemies within (.-) yards of you will gain a stack of Madness every (.-) sec, Slowing their Movement Speed by (.-)%% for (.-)%.%s*$","Você se transforma em um Destruidor sem rosto.\n\nDurante a transformação, causa {{1}}% a mais de dano e recebe {{2}}% menos dano. A cada {{3}} s, gera 10 de Insanidade e evoca um Tentáculo de N'Zoth próximo. Além disso, todos os inimigos em um raio de {{4}} m recebem um acúmulo de Loucura a cada {{5}} s, reduzindo a velocidade de movimento deles em {{6}}% durante {{7}}."}
T[14351]={"^Absorbs (.-) damage%. Magical Damage taken reduced by (.-)%%%.%s*$","Absorve {{1}} de dano. O dano mágico recebido é reduzido em {{2}}%."}
T[14359]={"^Your 3rd Eldritch Mending generates a Void Rune and consumes all stacks%.%s*$","Sua terceira Recomposição Sobrenatural gera uma Runa do Vazio e consome todos os acúmulos."}
T[14485]={"^Gives |cffffffffEldritch Blast|r and |cffffffffHorrorbolt|r a (.-)%% chance to cast |cFFFFFFFFNightmarish Bolt|r%.%s*$","Concede a |cffffffffExplosão Sobrenatural|r e |cffffffffSeta de Horror|r {{1}}% de chance de lançar |cFFFFFFFFSeta de Pesadelo|r."}
T[14486]={"^Gives your Eldritch Blast ability a chance to trigger twice%.%s*$","Concede a |cffffffffExplosão Sobrenatural|r uma chance de ser ativada duas vezes."}
T[15051]={"^Healing for 10%% of the damage dealt by Malevolence every (.-) sec%. Stacks (.-) times%.%s*$","Cura por 10% do dano causado por Malevolência a cada {{1}} s. Acumula {{2}} vezes."}
T[17419]={"^Dummy core script spell%. When caster has 276516, imps get 276517, which proc 276507 to caster%.%s*$","//script de feitiço dummy do núcleo. Quando o conjurador tem 276516, os duendes obtêm 276517, o que ativa 276507 paro conjurador."}
T[17917]={"^Refreshes 1 charge of Blade of the Empire%.%s*$","Recarga 1 carga de Lâmina do Império."}
T[17924]={"^At 3 stacks, your next Eldritch Mending or Prayer of Yogg%-Saron is instant cast and costs for (.-)%% less%.%s*$","Com 3 acúmulos, sua próxima Recomposição Sobrenatural ou Oração a Yogg-Saron é instantânea e custa {{1}}% menos."}
T[18604]={"^At 3 stacks, your next Malevolence is instant and costs (.-)%% less mana%.%s*$","Com 3 acúmulos, seu próximo Malevolência é instantâneo e custa {{1}}% menos de mana."}
T[18748]={"^|cFFFFFFFFHorrorbolt|r now grants |cFFFFFFFFInspired Malice|r for (.-)%.%s*$","|cFFFFFFFFSeta de Horror|r agora concede |cFFFFFFFFMalícia inspirada|r em {{1}}."}
T[18888]={"^At 5 stacks your Gaze of C'Thun transforms into Eldritch Force%.%s*$","Com 5 acúmulos, seu Olhar de C'Thun transforma-se em Força Místico."}
T[18972]={"^Every 3rd |cffffffffHorrorbolt|r causes your next successful |cffffffffHorrorbolt|r to deal an additional 50%% of the initial damage to the target over (.-)%.%s*$","A cada terceira |cffffffffSeta de Horror|r, a próxima |cffffffffSeta de Horror|r bem-sucedida causa ao alvo, durante {{1}}, dano adicional equivalente a 50% do dano inicial."}
T[18975]={"^Damage taken by Wrath of the Black Empire increased by 10%% per stack%s*$","O dano recebido de Ira do Império Negro aumenta em 10% por acúmulo."}
T[18976]={"^Your next Horrorbolt or Gaze of C'thun deals an additional 50%% of the initial damage over 3 sec%.%s*$","Seu próximo Seta de Horror ou Olhar de C'Thun causa mais 50% do dano inicial ao longo de 3 s."}
T[19003]={"^At 2 stacks, your next Horrorbolt will deal an additional 50%% of the initial damage over 1%.5 sec%.%s*$","Com 2 acúmulos, seu próximo Seta de Horror causará um adicional de 50% do dano inicial durante 1.5 s."}
T[19004]={"^Your next Horrorbolt deals (.-)%% increased damage plus an additional 30%% of the initial damage over 1%.5 sec%.%s*$","Seu próximo Seta de Horror causa dano aumentado em {{1}}% mais um adicional de 30% do dano inicial durante 1.5 s."}
T[19150]={"^Increases your casting speed by 20%%%. Reduces your magical damage dealt by 15%%%. Using Nether Reach on targets affected by Void Link will now provide additional Void Runes%.Shatter Void Rune will now grant you 1 stack of Rift Weaving%.%s*$","Aumenta sua velocidade de lançamento em 20% e reduz em 15% o dano Mágico causado. Usar |cffffffffAlcance do Vazio|r em alvos afetados por |cffffffffVínculo do Vazio|r agora concede Runas do Vazio adicionais. |cffffffffEstilhaçar Runa do Vazio|r agora concede 1 acúmulo de |cffffffffTecelagem da Fissura|r."}
T[19421]={"^Blade of the Empire now grants (.-)%% of your Intellect as Spell Critical Strike Rating for (.-), stacking 5 times%.%s*$","|cffffffffLâmina do Império|r agora concede, durante {{2}}, índice de acerto crítico com feitiços equivalente a {{1}}% do seu Intelecto, acumulando até 5 vezes."}
T[20317]={"^Your Crusader Strike reduce the cast time of your next Immolate, and gives it 2%% attack power scaling%. Stacking 3 times%.%s*$","Seu Golpe do Cruzado reduz o tempo de lançamento do seu próximo Imolar e concede a ele escalonamento de 2% do Poder de Ataque. Acumula até 3 vezes."}
T[20318]={"^Reduces the cast time of your next Immolate by (.-)%%%.%s*$","Reduz o tempo de lançamento de seu próximo Imolar em {{1}}%."}
T[21939]={"^Stamina increased by (.-)%.%s*$","vigor aumentado em {{1}}."}
T[22157]={"^Attack power increased by (.-)%.%s*$","Poder de ataque aumentou {{1}} p."}
T[25014]={"^(.-) Shadow damage inflicted every (.-) sec%.\nAttack and casting speeds reduced by (.-)%%%.%s*$","{{1}} p. de dano de Sombra causado a cada {{2}} s.\nvelocidades de ataque e de lançamento reduzidas {{3}}%."}
T[25058]={"^Disguised as a member of the Cult of the Damned%.  Looks out of place outside the Cathedral of Darkness%.%s*$","Disfarçado como um membro do Culto dos Malditos. Fica mal fora da Catedral da Escuridão."}

